INSERT INTO _e VALUES
 ('ENT_ISR_KINGS_JUDAH','The Kings of the Kingdom of Judah','Israelite/Second Temple','Collective','Biblical collective','the southern Davidic monarchy; kings of Judah from Rehoboam to Zedekiah','A','The succession of Davidic kings who ruled the southern Kingdom of Judah from the division of the monarchy until the Babylonian destruction of Jerusalem.'),
 ('ENT_ISR_KINGS_ISRAEL','The Kings of the Northern Kingdom of Israel','Israelite/Second Temple','Collective','Biblical collective','the breakaway northern monarchy; the dynasties of Israel','A','The succession of kings, across several dynasties, who ruled the breakaway northern Kingdom of Israel until its fall to Assyria.'),
 ('ENT_ISR_REHOBOAM','Rehoboam','Israelite/Second Temple','King','King of Judah','the division of the monarchy; first king of Judah; harsh counsel','A','Son of Solomon whose refusal to lighten the people''s burden provoked the northern tribes to secede, leaving him king of Judah alone.'),
 ('ENT_ISR_ASA','Asa','Israelite/Second Temple','King','King of Judah','cultic reform; removal of idols; war with Baasha','A','King of Judah praised for removing idols and reforming worship, who relied on an alliance with Aram against the northern kingdom.'),
 ('ENT_ISR_JEHOSHAPHAT','Jehoshaphat','Israelite/Second Temple','King','King of Judah','judicial reform; teaching of the law; alliance with Ahab','A','King of Judah remembered for instituting judges and Levitical teaching and for his ill-fated alliance with Ahab of Israel.'),
 ('ENT_ISR_AHAZ','Ahaz','Israelite/Second Temple','King','King of Judah','apostasy; the Syro-Ephraimite crisis; Assyrian vassalage','A','King of Judah condemned for idolatry who sought Assyrian protection against Aram and Israel during the Syro-Ephraimite war.'),
 ('ENT_ISR_UZZIAH','Uzziah (Azariah)','Israelite/Second Temple','King','King of Judah','military expansion; building; the leprous king','A','Long-reigning king of Judah who expanded the kingdom but was struck with leprosy after presuming to offer incense in the Temple.'),
 ('ENT_ISR_HEZEKIAH','Hezekiah','Israelite/Second Temple','King','King of Judah','cultic reform; deliverance from Sennacherib; the Siloam tunnel','A','Reforming king of Judah who centralized worship, withstood the Assyrian siege of Jerusalem, and was granted fifteen added years of life.'),
 ('ENT_ISR_MANASSEH','Manasseh (king of Judah)','Israelite/Second Temple','King','King of Judah','idolatry and bloodshed; the longest reign; later repentance','A','Longest-reigning king of Judah, condemned for grievous idolatry, whom Chronicles portrays as repenting after Assyrian captivity.'),
 ('ENT_ISR_JOSIAH','Josiah','Israelite/Second Temple','King','King of Judah','the great reform; the rediscovered book of the law; covenant renewal','A','Reforming king of Judah who, on the discovery of the book of the law, purged idolatry and renewed the covenant before dying at Megiddo.'),
 ('ENT_ISR_ZEDEKIAH','Zedekiah','Israelite/Second Temple','King','King of Judah','the last king of Judah; rebellion against Babylon; the fall of Jerusalem','A','Last king of Judah, installed by Nebuchadnezzar, whose rebellion brought the Babylonian destruction of Jerusalem and his own blinding and exile.'),
 ('ENT_ISR_JEROBOAM_I','Jeroboam I','Israelite/Second Temple','King','King of Israel','the northern secession; the golden calves of Dan and Bethel','A','First king of the breakaway northern Kingdom of Israel, who set up golden calves at Dan and Bethel and became the archetype of sinful kingship.'),
 ('ENT_ISR_OMRI','Omri','Israelite/Second Temple','King','King of Israel','dynastic founder; the building of Samaria','A','Northern king who founded a powerful dynasty and built Samaria as the capital of the Kingdom of Israel.'),
 ('ENT_ISR_AHAB','Ahab','Israelite/Second Temple','King','King of Israel','the Baal cult; conflict with Elijah; the house of Omri','A','Son of Omri and king of Israel who, married to Jezebel, promoted the worship of Baal and was repeatedly opposed by the prophet Elijah.'),
 ('ENT_ISR_JEHU','Jehu','Israelite/Second Temple','King','King of Israel','the purge of the house of Omri; zeal against Baal','A','Northern king anointed at Elisha''s direction who overthrew the house of Omri, killed Jezebel, and exterminated the worship of Baal in Israel.'),
 ('ENT_ISR_JEROBOAM_II','Jeroboam II','Israelite/Second Temple','King','King of Israel','territorial restoration; prosperity; the era of Amos and Hosea','A','Long-reigning northern king under whom Israel reached its greatest extent, the setting for the prophets Amos and Hosea.'),
 ('ENT_ISR_JEZEBEL','Jezebel','Israelite/Second Temple','Queen','Queen of Israel','promotion of Baal worship; persecution of the prophets; the Naboth affair','A','Phoenician wife of Ahab who promoted Baal worship, persecuted Yahweh''s prophets, and engineered the death of Naboth before her own violent end.'),
 ('ENT_ISR_GOLIATH','Goliath','Israelite/Second Temple','Villain','Philistine champion','the Philistine champion; the duel at the Valley of Elah','A','Philistine giant of Gath whose challenge to Israel was answered and ended by the young David with a sling and stone.'),
 ('ENT_ISR_JONATHAN','Jonathan (son of Saul)','Israelite/Second Temple','Hero','Crown prince of Israel','valor against the Philistines; covenant friendship with David','A','Eldest son of Saul, a brave warrior bound to David in covenant friendship, who fell with his father at the battle of Mount Gilboa.'),
 ('ENT_ISR_ABSALOM','Absalom','Israelite/Second Temple','Villain','Rebel prince','rebellion against David; the usurpation; death in the oak','A','Handsome son of David who rose in rebellion to seize the throne and was killed by Joab after his hair caught in an oak.'),
 ('ENT_ISR_BOAZ','Boaz','Israelite/Second Temple','Biblical figure','Kinsman-redeemer','the kinsman-redeemer; the marriage to Ruth; ancestor of David','A','Wealthy Bethlehemite who acted as kinsman-redeemer, married Ruth, and became the great-grandfather of King David.'),
 ('ENT_ISR_NAOMI','Naomi','Israelite/Second Temple','Biblical figure','Bethlehemite widow','bereavement and return; the bond with Ruth; restoration','A','Bethlehemite widow who returned from Moab with her daughter-in-law Ruth and was restored through the birth of Obed, ancestor of David.'),
 ('ENT_ISR_NAAMAN','Naaman','Israelite/Second Temple','Biblical figure','Aramean commander','foreign general; leprosy and healing; the seven dippings in the Jordan','A','Commander of the army of Aram, cured of leprosy by washing seven times in the Jordan at the word of the prophet Elisha.'),
 ('ENT_ISR_BALAAM','Balaam','Israelite/Second Temple','Biblical figure','Mesopotamian diviner','divination; the speaking donkey; blessing instead of cursing Israel','A','Mesopotamian seer hired by Balak of Moab to curse Israel who, restrained by Yahweh and his speaking donkey, blessed them instead.'),
 ('ENT_ISR_DELILAH','Delilah','Israelite/Second Temple','Villain','Philistine seductress','seduction and betrayal; the secret of Samson''s strength','A','Woman of the Valley of Sorek who, bribed by the Philistine lords, coaxed from Samson the secret of his strength and betrayed him.'),
 ('ENT_ISR_NEBUCHADNEZZAR','Nebuchadnezzar II','Israelite/Second Temple','Foreign king','King of Babylon','the conqueror of Jerusalem; the Babylonian exile; the dream visions','A','King of Babylon who destroyed Jerusalem and its Temple and carried Judah into exile, and whose dreams and madness frame the early chapters of Daniel.'),
 ('ENT_ISR_CYRUS','Cyrus the Great','Israelite/Second Temple','Foreign king','King of Persia','the conqueror of Babylon; the edict of return; the Lord''s anointed shepherd','A','Persian king who conquered Babylon and issued the decree permitting the exiles to return and rebuild the Temple in Jerusalem.'),
 ('ENT_NT_SEVEN_DEACONS','The Seven Deacons (Acts 6)','Christian/Biblical','Collective','Apostolic collective','the seven chosen to serve tables and oversee the daily distribution','A','The Seven chosen in Acts 6 to oversee the daily distribution to widows, traditionally regarded as the first deacons; named members include Stephen the protomartyr and Philip the Evangelist.'),
 ('ENT_NT_MYRRHBEARERS','The Myrrh-Bearing Women','Christian/Biblical','Collective','Apostolic collective','the women who came to anoint Jesus'' body; first witnesses of the Resurrection','A','The Myrrh-Bearing Women (Myrophoroi) who brought spices to anoint Jesus'' body and became the first witnesses of the Resurrection; commemorated as a group in Eastern tradition.'),
 ('ENT_NT_JAMES_JUST','James the Just','Christian/Biblical','Apostolic figure','Brother of the Lord','first bishop of Jerusalem; leader of the Jerusalem council; the Epistle of James','A','James ''the Lord''s brother'' (Gal 1:19), distinct from the apostolic Jameses, who presided over the Jerusalem church and the council of Acts 15 and is the traditional author of the Epistle of James.'),
 ('ENT_NT_JUDE','Jude (Brother of the Lord)','Christian/Biblical','Apostolic figure','Brother of the Lord','traditional author of the Epistle of Jude; named among the brothers of Jesus','A','Jude (Judas), named among the brothers of the Lord and identified in his epistle as ''brother of James''; traditional author of the canonical Epistle of Jude, distinguished here from the apostle Jude Thaddaeus.'),
 ('ENT_NT_PHILIP_EVANGELIST','Philip the Evangelist','Christian/Biblical','Deacon','Apostolic figure','one of the Seven Deacons; baptizer of the Ethiopian eunuch and of Samaria','A','One of the Seven chosen in Acts 6:5, later evangelizing Samaria and baptizing the Ethiopian eunuch; Acts 21:8 calls him ''the evangelist, one of the seven,'' distinguishing him from the apostle Philip.'),
 ('ENT_NT_SILAS','Silas','Christian/Biblical','Apostolic figure','Apostolic coworker','prophet of the Jerusalem church; companion of Paul; co-sender of the Thessalonian letters','A','Silas (Silvanus), a leading man and prophet of the Jerusalem church, chosen by Paul for the second journey and imprisoned with him at Philippi; co-sender of 1-2 Thessalonians.'),
 ('ENT_NT_APOLLOS','Apollos','Christian/Biblical','Apostolic figure','Apostolic coworker','Alexandrian Jewish teacher; eloquent preacher ''mighty in the Scriptures''','A','An eloquent Alexandrian Jew ''mighty in the Scriptures,'' instructed more fully by Priscilla and Aquila, then a powerful coworker at Corinth whom Paul names as a fellow planter.'),
 ('ENT_NT_PRISCILLA','Priscilla','Christian/Biblical','Apostolic figure','Apostolic coworker','tentmaker and missionary; with Aquila instructed Apollos and hosted a house church','A','Priscilla (Prisca), wife of Aquila and his constant ministry partner; together they instructed Apollos and hosted a house church, she frequently named first.'),
 ('ENT_NT_AQUILA','Aquila','Christian/Biblical','Apostolic figure','Apostolic coworker','Jewish tentmaker of Pontus; missionary coworker; host of a house church','A','Aquila, a Jew of Pontus and tentmaker, with his wife Priscilla a close coworker of Paul who instructed Apollos and hosted house churches at Ephesus and Rome.'),
 ('ENT_NT_LYDIA','Lydia of Thyatira','Christian/Biblical','Disciple','Apostolic figure','dealer in purple cloth; first recorded European convert; host of the Philippian church','A','A God-fearing dealer in purple goods from Thyatira at Philippi whose heart ''the Lord opened''; the first named convert in Europe, whose home became the base of the Philippian church.'),
 ('ENT_NT_JOSEPH_ARIMATHEA','Joseph of Arimathea','Christian/Biblical','Gospel figure','Disciple','member of the Sanhedrin; secret disciple who provided the tomb and buried Jesus','A','A rich and respected councillor and secret disciple who asked Pilate for the body of Jesus and laid it in his own new rock-cut tomb; present in all four Gospels.'),
 ('ENT_NT_MARY_BETHANY','Mary of Bethany','Christian/Biblical','Disciple','Gospel figure','sister of Lazarus and Martha; sat at Jesus'' feet; anointed him at Bethany','A','Sister of Martha and Lazarus, who sat at Jesus'' feet to learn (Luke 10) and anointed his feet with costly nard before the Passion (John 12); distinct from Mary Magdalene.'),
 ('ENT_NT_SALOME','Salome (the Myrrh-Bearer)','Christian/Biblical','Disciple','Gospel figure','Galilean woman follower; witness at the crucifixion; myrrh-bearer at the tomb','A','One of the Galilean women who followed Jesus, present at the crucifixion and among those who came to the tomb with spices; often identified with the mother of the sons of Zebedee, and distinct from Salome daughter of Herodias.'),
 ('ENT_NT_ZACCHAEUS','Zacchaeus','Christian/Biblical','Gospel figure','Disciple','chief tax collector at Jericho; convert who restored fourfold','A','A wealthy chief tax collector at Jericho who climbed a sycamore to see Jesus, received him, and pledged half his goods to the poor and fourfold restitution.'),
 ('ENT_NT_MARY_OF_JAMES','Mary, mother of James','Christian/Biblical','Disciple','Gospel figure','Galilean woman follower; witness at the crucifixion and empty tomb; myrrh-bearer','A','Mary the mother of James the younger and Joses, one of the Galilean women at the cross and among the myrrh-bearers who found the empty tomb (''the other Mary'').'),
 ('ENT_NT_PILATE','Pontius Pilate','Christian/Biblical','Roman official','Gospel antagonist','Roman prefect of Judaea; the judge who condemned Jesus to crucifixion','A','The Roman prefect of Judaea who tried Jesus and ordered the crucifixion; named in the creeds and confirmed epigraphically by the Pilate Stone.'),
 ('ENT_NT_HEROD_GREAT','Herod the Great','Christian/Biblical','Ruler','Gospel antagonist','Roman client king of Judaea; ordered the Massacre of the Innocents','A','Rome''s client king of Judaea, the Herod of the Nativity who, alarmed by the Magi, ordered the killing of the infants of Bethlehem; abundantly attested by Josephus.'),
 ('ENT_NT_HEROD_ANTIPAS','Herod Antipas','Christian/Biblical','Ruler','Gospel antagonist','tetrarch of Galilee and Perea; executed John the Baptist; examined Jesus','A','Tetrarch of Galilee and Perea, son of Herod the Great, who imprisoned and beheaded John the Baptist and to whom Pilate sent Jesus during the trial.'),
 ('ENT_NT_CAIAPHAS','Caiaphas','Christian/Biblical','High priest','Gospel antagonist','Jewish high priest; presided over the Sanhedrin trial of Jesus','A','Joseph Caiaphas, high priest who convened the Sanhedrin against Jesus and counseled that one man should die for the people; son-in-law of Annas, plausibly attested by the inscribed ossuary found in Jerusalem.'),
 ('ENT_ISL_RASHIDUN','The Rashidun — the Rightly-Guided Caliphs','Islamic','Collective','Islamic companion','the first four caliphs; rightly-guided succession; the early Islamic state','A','The first four caliphs of Islam — Abu Bakr, Umar, Uthman, and Ali — regarded in Sunni tradition as the ''Rightly-Guided'' successors of the Prophet (632-661 CE).'),
 ('ENT_ISL_SAHABA','The Sahaba — Companions of the Prophet','Islamic','Collective','Islamic companion','companions of the Prophet; the first generation of Muslims; transmitters of the faith','A','The companions who knew, accompanied, or saw the Prophet Muhammad and embraced Islam, forming the first generation of Muslims and the chain of transmission for the faith.'),
 ('ENT_ISL_UMMAHAT','Ummahat al-Mu''minin — the Mothers of the Believers','Islamic','Collective','Islamic companion','wives of the Prophet; mothers of the believers','A','The wives of the Prophet Muhammad, given this honorific title in the Qur''an (33:6).'),
 ('ENT_ISL_TEN_PROMISED','The Ten Promised Paradise (al-Ashara al-Mubashshara)','Islamic','Collective','Islamic companion','ten companions promised paradise; elite companions','A','The ten companions whom the Prophet reportedly named as assured of paradise during their lifetimes, including Abu Bakr, Umar, Uthman, and Ali.'),
 ('ENT_ISL_ABU_BAKR','Abu Bakr','Islamic','Caliph','Islamic companion','first Rashidun caliph; closest companion of the Prophet; first adult male convert','A','Abu Bakr al-Siddiq, the Prophet''s closest companion and father-in-law, who became the first Rightly-Guided Caliph (632-634 CE).'),
 ('ENT_ISL_UMAR','Umar ibn al-Khattab','Islamic','Caliph','Islamic companion','second Rashidun caliph; expansion of the state; justice and administration','A','Umar ibn al-Khattab al-Faruq, the second Rightly-Guided Caliph (634-644 CE), under whom the early conquests greatly expanded, renowned for his austere justice.'),
 ('ENT_ISL_UTHMAN','Uthman ibn Affan','Islamic','Caliph','Islamic companion','third Rashidun caliph; the standardized Quran; early convert','A','Uthman ibn Affan, the third Rightly-Guided Caliph (644-656 CE), credited with commissioning the standardized written compilation of the Quran, and a son-in-law of the Prophet.'),
 ('ENT_ISL_HAMZA','Hamza ibn Abd al-Muttalib','Islamic','Companion','Islamic companion','uncle of the Prophet; warrior; martyr of Uhud','A','A paternal uncle of the Prophet, the celebrated warrior titled ''Lion of God,'' killed at the Battle of Uhud (625 CE).'),
 ('ENT_ISL_BILAL','Bilal ibn Rabah','Islamic','Companion','Islamic companion','first muezzin; early convert; formerly enslaved','A','An Abyssinian formerly enslaved and freed by Abu Bakr, an early convert and the first muezzin (caller to prayer) of Islam.'),
 ('ENT_ISL_SALMAN','Salman al-Farsi','Islamic','Companion','Islamic companion','Persian convert; strategist of the Trench; seeker of true religion','A','Salman the Persian, a companion who advised digging the defensive trench at the Battle of the Trench (627 CE) and was honored as a member of the Prophet''s household.'),
 ('ENT_ISL_KHALID','Khalid ibn al-Walid','Islamic','Military commander','Islamic companion','general; military conquests; undefeated commander','A','Titled ''Sword of God,'' the foremost military commander of early Islam, leading campaigns in the Ridda wars and the conquests of Iraq and Syria.'),
 ('ENT_ISL_ABU_HURAYRA','Abu Hurayra','Islamic','Hadith narrator','Islamic companion','foremost hadith narrator; transmission of prophetic tradition','A','A companion who became the most prolific narrator of hadith in the Sunni tradition.'),
 ('ENT_ISL_ZAYD','Zayd ibn Haritha','Islamic','Companion','Islamic companion','adopted son of the Prophet; commander; martyr of Mu''ta','A','A freedman and adopted son of the Prophet, the only companion named in the Quran, who died as a commander at the Battle of Mu''ta (629 CE).'),
 ('ENT_ISL_JAFAR','Ja''far ibn Abi Talib','Islamic','Companion','Islamic companion','cousin of the Prophet; leader of the Abyssinia migration; martyr of Mu''ta','A','Brother of Ali and cousin of the Prophet, who led the migration to Abyssinia and died as a commander at Mu''ta (629 CE), titled ''Ja''far the Flyer.'''),
 ('ENT_ISL_ABU_TALIB','Abu Talib','Islamic','Companion','Islamic kin','uncle and protector of the Prophet; chief of Banu Hashim; father of Ali','B','The paternal uncle who raised the orphaned Muhammad and protected him during the early Meccan persecution as chief of the Banu Hashim.'),
 ('ENT_ISL_ABD_AL_MUTTALIB','Abd al-Muttalib','Islamic','Companion','Islamic kin','grandfather of the Prophet; chief of Quraysh; custodian of the Kaaba','B','The grandfather of the Prophet Muhammad and a leading chief of the Quraysh who served as custodian of the Kaaba in Mecca.'),
 ('ENT_ISL_KHADIJAH','Khadijah bint Khuwaylid','Islamic','Mother of the Believers','Islamic companion','first wife of the Prophet; first believer; merchant patron','A','The first wife of the Prophet Muhammad, a wealthy Meccan merchant and the first person to accept Islam.'),
 ('ENT_ISL_AISHA','Aisha bint Abi Bakr','Islamic','Mother of the Believers','Islamic companion','wife of the Prophet; hadith narrator and scholar; daughter of Abu Bakr','A','A wife of the Prophet and daughter of Abu Bakr, who became a foremost narrator of hadith and authority on Islamic law and tradition.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_ISR_KINGS_JUDAH','SRC_HEBREW_BIBLE','The succession of Davidic kings who ruled the southern Kingdom of Judah from the division of the monarchy until the Babylonian destruction of Jerusalem.','primary text attestation'),
 ('ENT_ISR_KINGS_ISRAEL','SRC_HEBREW_BIBLE','The succession of kings, across several dynasties, who ruled the breakaway northern Kingdom of Israel until its fall to Assyria.','primary text attestation'),
 ('ENT_ISR_REHOBOAM','SRC_HEBREW_BIBLE','Son of Solomon whose refusal to lighten the people''s burden provoked the northern tribes to secede, leaving him king of Judah alone.','primary text attestation'),
 ('ENT_ISR_ASA','SRC_HEBREW_BIBLE','King of Judah praised for removing idols and reforming worship, who relied on an alliance with Aram against the northern kingdom.','primary text attestation'),
 ('ENT_ISR_JEHOSHAPHAT','SRC_HEBREW_BIBLE','King of Judah remembered for instituting judges and Levitical teaching and for his ill-fated alliance with Ahab of Israel.','primary text attestation'),
 ('ENT_ISR_AHAZ','SRC_HEBREW_BIBLE','King of Judah condemned for idolatry who sought Assyrian protection against Aram and Israel during the Syro-Ephraimite war.','primary text attestation'),
 ('ENT_ISR_UZZIAH','SRC_HEBREW_BIBLE','Long-reigning king of Judah who expanded the kingdom but was struck with leprosy after presuming to offer incense in the Temple.','primary text attestation'),
 ('ENT_ISR_HEZEKIAH','SRC_HEBREW_BIBLE','Reforming king of Judah who centralized worship, withstood the Assyrian siege of Jerusalem, and was granted fifteen added years of life.','primary text attestation'),
 ('ENT_ISR_MANASSEH','SRC_HEBREW_BIBLE','Longest-reigning king of Judah, condemned for grievous idolatry, whom Chronicles portrays as repenting after Assyrian captivity.','primary text attestation'),
 ('ENT_ISR_JOSIAH','SRC_HEBREW_BIBLE','Reforming king of Judah who, on the discovery of the book of the law, purged idolatry and renewed the covenant before dying at Megiddo.','primary text attestation'),
 ('ENT_ISR_ZEDEKIAH','SRC_HEBREW_BIBLE','Last king of Judah, installed by Nebuchadnezzar, whose rebellion brought the Babylonian destruction of Jerusalem and his own blinding and exile.','primary text attestation'),
 ('ENT_ISR_JEROBOAM_I','SRC_HEBREW_BIBLE','First king of the breakaway northern Kingdom of Israel, who set up golden calves at Dan and Bethel and became the archetype of sinful kingship.','primary text attestation'),
 ('ENT_ISR_OMRI','SRC_HEBREW_BIBLE','Northern king who founded a powerful dynasty and built Samaria as the capital of the Kingdom of Israel.','primary text attestation'),
 ('ENT_ISR_AHAB','SRC_HEBREW_BIBLE','Son of Omri and king of Israel who, married to Jezebel, promoted the worship of Baal and was repeatedly opposed by the prophet Elijah.','primary text attestation'),
 ('ENT_ISR_JEHU','SRC_HEBREW_BIBLE','Northern king anointed at Elisha''s direction who overthrew the house of Omri, killed Jezebel, and exterminated the worship of Baal in Israel.','primary text attestation'),
 ('ENT_ISR_JEROBOAM_II','SRC_HEBREW_BIBLE','Long-reigning northern king under whom Israel reached its greatest extent, the setting for the prophets Amos and Hosea.','primary text attestation'),
 ('ENT_ISR_JEZEBEL','SRC_HEBREW_BIBLE','Phoenician wife of Ahab who promoted Baal worship, persecuted Yahweh''s prophets, and engineered the death of Naboth before her own violent end.','primary text attestation'),
 ('ENT_ISR_GOLIATH','SRC_HEBREW_BIBLE','Philistine giant of Gath whose challenge to Israel was answered and ended by the young David with a sling and stone.','primary text attestation'),
 ('ENT_ISR_JONATHAN','SRC_HEBREW_BIBLE','Eldest son of Saul, a brave warrior bound to David in covenant friendship, who fell with his father at the battle of Mount Gilboa.','primary text attestation'),
 ('ENT_ISR_ABSALOM','SRC_HEBREW_BIBLE','Handsome son of David who rose in rebellion to seize the throne and was killed by Joab after his hair caught in an oak.','primary text attestation'),
 ('ENT_ISR_BOAZ','SRC_HEBREW_BIBLE','Wealthy Bethlehemite who acted as kinsman-redeemer, married Ruth, and became the great-grandfather of King David.','primary text attestation'),
 ('ENT_ISR_NAOMI','SRC_HEBREW_BIBLE','Bethlehemite widow who returned from Moab with her daughter-in-law Ruth and was restored through the birth of Obed, ancestor of David.','primary text attestation'),
 ('ENT_ISR_NAAMAN','SRC_HEBREW_BIBLE','Commander of the army of Aram, cured of leprosy by washing seven times in the Jordan at the word of the prophet Elisha.','primary text attestation'),
 ('ENT_ISR_BALAAM','SRC_HEBREW_BIBLE','Mesopotamian seer hired by Balak of Moab to curse Israel who, restrained by Yahweh and his speaking donkey, blessed them instead.','primary text attestation'),
 ('ENT_ISR_DELILAH','SRC_HEBREW_BIBLE','Woman of the Valley of Sorek who, bribed by the Philistine lords, coaxed from Samson the secret of his strength and betrayed him.','primary text attestation'),
 ('ENT_ISR_NEBUCHADNEZZAR','SRC_HEBREW_BIBLE','King of Babylon who destroyed Jerusalem and its Temple and carried Judah into exile, and whose dreams and madness frame the early chapters of Daniel.','primary text attestation'),
 ('ENT_ISR_CYRUS','SRC_HEBREW_BIBLE','Persian king who conquered Babylon and issued the decree permitting the exiles to return and rebuild the Temple in Jerusalem.','primary text attestation'),
 ('ENT_NT_SEVEN_DEACONS','SRC_NEW_TESTAMENT','The Seven chosen in Acts 6 to oversee the daily distribution to widows, traditionally regarded as the first deacons; named members include Stephen the protomartyr and Philip the Evangelist.','primary text attestation'),
 ('ENT_NT_MYRRHBEARERS','SRC_NEW_TESTAMENT','The Myrrh-Bearing Women (Myrophoroi) who brought spices to anoint Jesus'' body and became the first witnesses of the Resurrection; commemorated as a group in Eastern tradition.','primary text attestation'),
 ('ENT_NT_JAMES_JUST','SRC_NEW_TESTAMENT','James ''the Lord''s brother'' (Gal 1:19), distinct from the apostolic Jameses, who presided over the Jerusalem church and the council of Acts 15 and is the traditional author of the Epistle of James.','primary text attestation'),
 ('ENT_NT_JUDE','SRC_NEW_TESTAMENT','Jude (Judas), named among the brothers of the Lord and identified in his epistle as ''brother of James''; traditional author of the canonical Epistle of Jude, distinguished here from the apostle Jude Thaddaeus.','primary text attestation'),
 ('ENT_NT_PHILIP_EVANGELIST','SRC_NEW_TESTAMENT','One of the Seven chosen in Acts 6:5, later evangelizing Samaria and baptizing the Ethiopian eunuch; Acts 21:8 calls him ''the evangelist, one of the seven,'' distinguishing him from the apostle Philip.','primary text attestation'),
 ('ENT_NT_SILAS','SRC_NEW_TESTAMENT','Silas (Silvanus), a leading man and prophet of the Jerusalem church, chosen by Paul for the second journey and imprisoned with him at Philippi; co-sender of 1-2 Thessalonians.','primary text attestation'),
 ('ENT_NT_APOLLOS','SRC_NEW_TESTAMENT','An eloquent Alexandrian Jew ''mighty in the Scriptures,'' instructed more fully by Priscilla and Aquila, then a powerful coworker at Corinth whom Paul names as a fellow planter.','primary text attestation'),
 ('ENT_NT_PRISCILLA','SRC_NEW_TESTAMENT','Priscilla (Prisca), wife of Aquila and his constant ministry partner; together they instructed Apollos and hosted a house church, she frequently named first.','primary text attestation'),
 ('ENT_NT_AQUILA','SRC_NEW_TESTAMENT','Aquila, a Jew of Pontus and tentmaker, with his wife Priscilla a close coworker of Paul who instructed Apollos and hosted house churches at Ephesus and Rome.','primary text attestation'),
 ('ENT_NT_LYDIA','SRC_NEW_TESTAMENT','A God-fearing dealer in purple goods from Thyatira at Philippi whose heart ''the Lord opened''; the first named convert in Europe, whose home became the base of the Philippian church.','primary text attestation'),
 ('ENT_NT_JOSEPH_ARIMATHEA','SRC_NEW_TESTAMENT','A rich and respected councillor and secret disciple who asked Pilate for the body of Jesus and laid it in his own new rock-cut tomb; present in all four Gospels.','primary text attestation'),
 ('ENT_NT_MARY_BETHANY','SRC_NEW_TESTAMENT','Sister of Martha and Lazarus, who sat at Jesus'' feet to learn (Luke 10) and anointed his feet with costly nard before the Passion (John 12); distinct from Mary Magdalene.','primary text attestation'),
 ('ENT_NT_SALOME','SRC_NEW_TESTAMENT','One of the Galilean women who followed Jesus, present at the crucifixion and among those who came to the tomb with spices; often identified with the mother of the sons of Zebedee, and distinct from Salome daughter of Herodias.','primary text attestation'),
 ('ENT_NT_ZACCHAEUS','SRC_NEW_TESTAMENT','A wealthy chief tax collector at Jericho who climbed a sycamore to see Jesus, received him, and pledged half his goods to the poor and fourfold restitution.','primary text attestation'),
 ('ENT_NT_MARY_OF_JAMES','SRC_NEW_TESTAMENT','Mary the mother of James the younger and Joses, one of the Galilean women at the cross and among the myrrh-bearers who found the empty tomb (''the other Mary'').','primary text attestation'),
 ('ENT_NT_PILATE','SRC_NEW_TESTAMENT','The Roman prefect of Judaea who tried Jesus and ordered the crucifixion; named in the creeds and confirmed epigraphically by the Pilate Stone.','primary text attestation'),
 ('ENT_NT_HEROD_GREAT','SRC_NEW_TESTAMENT','Rome''s client king of Judaea, the Herod of the Nativity who, alarmed by the Magi, ordered the killing of the infants of Bethlehem; abundantly attested by Josephus.','primary text attestation'),
 ('ENT_NT_HEROD_ANTIPAS','SRC_NEW_TESTAMENT','Tetrarch of Galilee and Perea, son of Herod the Great, who imprisoned and beheaded John the Baptist and to whom Pilate sent Jesus during the trial.','primary text attestation'),
 ('ENT_NT_CAIAPHAS','SRC_NEW_TESTAMENT','Joseph Caiaphas, high priest who convened the Sanhedrin against Jesus and counseled that one man should die for the people; son-in-law of Annas, plausibly attested by the inscribed ossuary found in Jerusalem.','primary text attestation'),
 ('ENT_ISL_RASHIDUN','SRC_SAHIH_BUKHARI','The first four caliphs of Islam — Abu Bakr, Umar, Uthman, and Ali — regarded in Sunni tradition as the ''Rightly-Guided'' successors of the Prophet (632-661 CE).','scholarly attestation'),
 ('ENT_ISL_SAHABA','SRC_IBN_ISHAQ_SIRA','The companions who knew, accompanied, or saw the Prophet Muhammad and embraced Islam, forming the first generation of Muslims and the chain of transmission for the faith.','scholarly attestation'),
 ('ENT_ISL_UMMAHAT','SRC_SAHIH_BUKHARI','The wives of the Prophet Muhammad, given this honorific title in the Qur''an (33:6).','scholarly attestation'),
 ('ENT_ISL_TEN_PROMISED','SRC_SAHIH_BUKHARI','The ten companions whom the Prophet reportedly named as assured of paradise during their lifetimes, including Abu Bakr, Umar, Uthman, and Ali.','scholarly attestation'),
 ('ENT_ISL_ABU_BAKR','SRC_SAHIH_BUKHARI','Abu Bakr al-Siddiq, the Prophet''s closest companion and father-in-law, who became the first Rightly-Guided Caliph (632-634 CE).','scholarly attestation'),
 ('ENT_ISL_UMAR','SRC_SAHIH_BUKHARI','Umar ibn al-Khattab al-Faruq, the second Rightly-Guided Caliph (634-644 CE), under whom the early conquests greatly expanded, renowned for his austere justice.','scholarly attestation'),
 ('ENT_ISL_UTHMAN','SRC_SAHIH_BUKHARI','Uthman ibn Affan, the third Rightly-Guided Caliph (644-656 CE), credited with commissioning the standardized written compilation of the Quran, and a son-in-law of the Prophet.','scholarly attestation'),
 ('ENT_ISL_HAMZA','SRC_IBN_ISHAQ_SIRA','A paternal uncle of the Prophet, the celebrated warrior titled ''Lion of God,'' killed at the Battle of Uhud (625 CE).','scholarly attestation'),
 ('ENT_ISL_BILAL','SRC_IBN_ISHAQ_SIRA','An Abyssinian formerly enslaved and freed by Abu Bakr, an early convert and the first muezzin (caller to prayer) of Islam.','scholarly attestation'),
 ('ENT_ISL_SALMAN','SRC_IBN_ISHAQ_SIRA','Salman the Persian, a companion who advised digging the defensive trench at the Battle of the Trench (627 CE) and was honored as a member of the Prophet''s household.','scholarly attestation'),
 ('ENT_ISL_KHALID','SRC_IBN_ISHAQ_SIRA','Titled ''Sword of God,'' the foremost military commander of early Islam, leading campaigns in the Ridda wars and the conquests of Iraq and Syria.','scholarly attestation'),
 ('ENT_ISL_ABU_HURAYRA','SRC_SAHIH_BUKHARI','A companion who became the most prolific narrator of hadith in the Sunni tradition.','scholarly attestation'),
 ('ENT_ISL_ZAYD','SRC_IBN_ISHAQ_SIRA','A freedman and adopted son of the Prophet, the only companion named in the Quran, who died as a commander at the Battle of Mu''ta (629 CE).','scholarly attestation'),
 ('ENT_ISL_JAFAR','SRC_IBN_ISHAQ_SIRA','Brother of Ali and cousin of the Prophet, who led the migration to Abyssinia and died as a commander at Mu''ta (629 CE), titled ''Ja''far the Flyer.''','scholarly attestation'),
 ('ENT_ISL_ABU_TALIB','SRC_IBN_ISHAQ_SIRA','The paternal uncle who raised the orphaned Muhammad and protected him during the early Meccan persecution as chief of the Banu Hashim.','scholarly attestation'),
 ('ENT_ISL_ABD_AL_MUTTALIB','SRC_IBN_ISHAQ_SIRA','The grandfather of the Prophet Muhammad and a leading chief of the Quraysh who served as custodian of the Kaaba in Mecca.','scholarly attestation'),
 ('ENT_ISL_KHADIJAH','SRC_IBN_ISHAQ_SIRA','The first wife of the Prophet Muhammad, a wealthy Meccan merchant and the first person to accept Islam.','scholarly attestation'),
 ('ENT_ISL_AISHA','SRC_SAHIH_BUKHARI','A wife of the Prophet and daughter of Abu Bakr, who became a foremost narrator of hadith and authority on Islamic law and tradition.','scholarly attestation');
INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_ISR_KINGS_JUDAH','PER_ISR_IRON_AGE','The succession of Davidic kings who ruled the southern Kingdom of Judah from the division of the monarchy until the Babylonian destruction of Jerusalem.'),
 ('ENT_ISR_KINGS_ISRAEL','PER_ISR_IRON_AGE','The succession of kings, across several dynasties, who ruled the breakaway northern Kingdom of Israel until its fall to Assyria.'),
 ('ENT_ISR_REHOBOAM','PER_ISR_IRON_AGE','Son of Solomon whose refusal to lighten the people''s burden provoked the northern tribes to secede, leaving him king of Judah alone.'),
 ('ENT_ISR_ASA','PER_ISR_IRON_AGE','King of Judah praised for removing idols and reforming worship, who relied on an alliance with Aram against the northern kingdom.'),
 ('ENT_ISR_JEHOSHAPHAT','PER_ISR_IRON_AGE','King of Judah remembered for instituting judges and Levitical teaching and for his ill-fated alliance with Ahab of Israel.'),
 ('ENT_ISR_AHAZ','PER_ISR_IRON_AGE','King of Judah condemned for idolatry who sought Assyrian protection against Aram and Israel during the Syro-Ephraimite war.'),
 ('ENT_ISR_UZZIAH','PER_ISR_IRON_AGE','Long-reigning king of Judah who expanded the kingdom but was struck with leprosy after presuming to offer incense in the Temple.'),
 ('ENT_ISR_HEZEKIAH','PER_ISR_IRON_AGE','Reforming king of Judah who centralized worship, withstood the Assyrian siege of Jerusalem, and was granted fifteen added years of life.'),
 ('ENT_ISR_MANASSEH','PER_ISR_IRON_AGE','Longest-reigning king of Judah, condemned for grievous idolatry, whom Chronicles portrays as repenting after Assyrian captivity.'),
 ('ENT_ISR_JOSIAH','PER_ISR_IRON_AGE','Reforming king of Judah who, on the discovery of the book of the law, purged idolatry and renewed the covenant before dying at Megiddo.'),
 ('ENT_ISR_ZEDEKIAH','PER_ISR_EXILIC','Last king of Judah, installed by Nebuchadnezzar, whose rebellion brought the Babylonian destruction of Jerusalem and his own blinding and exile.'),
 ('ENT_ISR_JEROBOAM_I','PER_ISR_IRON_AGE','First king of the breakaway northern Kingdom of Israel, who set up golden calves at Dan and Bethel and became the archetype of sinful kingship.'),
 ('ENT_ISR_OMRI','PER_ISR_IRON_AGE','Northern king who founded a powerful dynasty and built Samaria as the capital of the Kingdom of Israel.'),
 ('ENT_ISR_AHAB','PER_ISR_IRON_AGE','Son of Omri and king of Israel who, married to Jezebel, promoted the worship of Baal and was repeatedly opposed by the prophet Elijah.'),
 ('ENT_ISR_JEHU','PER_ISR_IRON_AGE','Northern king anointed at Elisha''s direction who overthrew the house of Omri, killed Jezebel, and exterminated the worship of Baal in Israel.'),
 ('ENT_ISR_JEROBOAM_II','PER_ISR_IRON_AGE','Long-reigning northern king under whom Israel reached its greatest extent, the setting for the prophets Amos and Hosea.'),
 ('ENT_ISR_JEZEBEL','PER_ISR_IRON_AGE','Phoenician wife of Ahab who promoted Baal worship, persecuted Yahweh''s prophets, and engineered the death of Naboth before her own violent end.'),
 ('ENT_ISR_GOLIATH','PER_ISR_IRON_AGE','Philistine giant of Gath whose challenge to Israel was answered and ended by the young David with a sling and stone.'),
 ('ENT_ISR_JONATHAN','PER_ISR_IRON_AGE','Eldest son of Saul, a brave warrior bound to David in covenant friendship, who fell with his father at the battle of Mount Gilboa.'),
 ('ENT_ISR_ABSALOM','PER_ISR_IRON_AGE','Handsome son of David who rose in rebellion to seize the throne and was killed by Joab after his hair caught in an oak.'),
 ('ENT_ISR_BOAZ','PER_ISR_IRON_AGE','Wealthy Bethlehemite who acted as kinsman-redeemer, married Ruth, and became the great-grandfather of King David.'),
 ('ENT_ISR_NAOMI','PER_ISR_IRON_AGE','Bethlehemite widow who returned from Moab with her daughter-in-law Ruth and was restored through the birth of Obed, ancestor of David.'),
 ('ENT_ISR_NAAMAN','PER_ISR_IRON_AGE','Commander of the army of Aram, cured of leprosy by washing seven times in the Jordan at the word of the prophet Elisha.'),
 ('ENT_ISR_BALAAM','PER_ISR_IRON_AGE','Mesopotamian seer hired by Balak of Moab to curse Israel who, restrained by Yahweh and his speaking donkey, blessed them instead.'),
 ('ENT_ISR_DELILAH','PER_ISR_IRON_AGE','Woman of the Valley of Sorek who, bribed by the Philistine lords, coaxed from Samson the secret of his strength and betrayed him.'),
 ('ENT_ISR_NEBUCHADNEZZAR','PER_ISR_EXILIC','King of Babylon who destroyed Jerusalem and its Temple and carried Judah into exile, and whose dreams and madness frame the early chapters of Daniel.'),
 ('ENT_ISR_CYRUS','PER_ISR_EXILIC','Persian king who conquered Babylon and issued the decree permitting the exiles to return and rebuild the Temple in Jerusalem.'),
 ('ENT_NT_SEVEN_DEACONS','PER_APOSTOLIC','The Seven chosen in Acts 6 to oversee the daily distribution to widows, traditionally regarded as the first deacons; named members include Stephen the protomartyr and Philip the Evangelist.'),
 ('ENT_NT_MYRRHBEARERS','PER_APOSTOLIC','The Myrrh-Bearing Women (Myrophoroi) who brought spices to anoint Jesus'' body and became the first witnesses of the Resurrection; commemorated as a group in Eastern tradition.'),
 ('ENT_NT_JAMES_JUST','PER_APOSTOLIC','James ''the Lord''s brother'' (Gal 1:19), distinct from the apostolic Jameses, who presided over the Jerusalem church and the council of Acts 15 and is the traditional author of the Epistle of James.'),
 ('ENT_NT_JUDE','PER_APOSTOLIC','Jude (Judas), named among the brothers of the Lord and identified in his epistle as ''brother of James''; traditional author of the canonical Epistle of Jude, distinguished here from the apostle Jude Thaddaeus.'),
 ('ENT_NT_PHILIP_EVANGELIST','PER_APOSTOLIC','One of the Seven chosen in Acts 6:5, later evangelizing Samaria and baptizing the Ethiopian eunuch; Acts 21:8 calls him ''the evangelist, one of the seven,'' distinguishing him from the apostle Philip.'),
 ('ENT_NT_SILAS','PER_APOSTOLIC','Silas (Silvanus), a leading man and prophet of the Jerusalem church, chosen by Paul for the second journey and imprisoned with him at Philippi; co-sender of 1-2 Thessalonians.'),
 ('ENT_NT_APOLLOS','PER_APOSTOLIC','An eloquent Alexandrian Jew ''mighty in the Scriptures,'' instructed more fully by Priscilla and Aquila, then a powerful coworker at Corinth whom Paul names as a fellow planter.'),
 ('ENT_NT_PRISCILLA','PER_APOSTOLIC','Priscilla (Prisca), wife of Aquila and his constant ministry partner; together they instructed Apollos and hosted a house church, she frequently named first.'),
 ('ENT_NT_AQUILA','PER_APOSTOLIC','Aquila, a Jew of Pontus and tentmaker, with his wife Priscilla a close coworker of Paul who instructed Apollos and hosted house churches at Ephesus and Rome.'),
 ('ENT_NT_LYDIA','PER_APOSTOLIC','A God-fearing dealer in purple goods from Thyatira at Philippi whose heart ''the Lord opened''; the first named convert in Europe, whose home became the base of the Philippian church.'),
 ('ENT_NT_JOSEPH_ARIMATHEA','PER_APOSTOLIC','A rich and respected councillor and secret disciple who asked Pilate for the body of Jesus and laid it in his own new rock-cut tomb; present in all four Gospels.'),
 ('ENT_NT_MARY_BETHANY','PER_APOSTOLIC','Sister of Martha and Lazarus, who sat at Jesus'' feet to learn (Luke 10) and anointed his feet with costly nard before the Passion (John 12); distinct from Mary Magdalene.'),
 ('ENT_NT_SALOME','PER_APOSTOLIC','One of the Galilean women who followed Jesus, present at the crucifixion and among those who came to the tomb with spices; often identified with the mother of the sons of Zebedee, and distinct from Salome daughter of Herodias.'),
 ('ENT_NT_ZACCHAEUS','PER_APOSTOLIC','A wealthy chief tax collector at Jericho who climbed a sycamore to see Jesus, received him, and pledged half his goods to the poor and fourfold restitution.'),
 ('ENT_NT_MARY_OF_JAMES','PER_APOSTOLIC','Mary the mother of James the younger and Joses, one of the Galilean women at the cross and among the myrrh-bearers who found the empty tomb (''the other Mary'').'),
 ('ENT_NT_PILATE','PER_APOSTOLIC','The Roman prefect of Judaea who tried Jesus and ordered the crucifixion; named in the creeds and confirmed epigraphically by the Pilate Stone.'),
 ('ENT_NT_HEROD_GREAT','PER_APOSTOLIC','Rome''s client king of Judaea, the Herod of the Nativity who, alarmed by the Magi, ordered the killing of the infants of Bethlehem; abundantly attested by Josephus.'),
 ('ENT_NT_HEROD_ANTIPAS','PER_APOSTOLIC','Tetrarch of Galilee and Perea, son of Herod the Great, who imprisoned and beheaded John the Baptist and to whom Pilate sent Jesus during the trial.'),
 ('ENT_NT_CAIAPHAS','PER_APOSTOLIC','Joseph Caiaphas, high priest who convened the Sanhedrin against Jesus and counseled that one man should die for the people; son-in-law of Annas, plausibly attested by the inscribed ossuary found in Jerusalem.'),
 ('ENT_ISL_RASHIDUN','PER_ISL_EARLY','The first four caliphs of Islam — Abu Bakr, Umar, Uthman, and Ali — regarded in Sunni tradition as the ''Rightly-Guided'' successors of the Prophet (632-661 CE).'),
 ('ENT_ISL_SAHABA','PER_ISL_EARLY','The companions who knew, accompanied, or saw the Prophet Muhammad and embraced Islam, forming the first generation of Muslims and the chain of transmission for the faith.'),
 ('ENT_ISL_UMMAHAT','PER_ISL_EARLY','The wives of the Prophet Muhammad, given this honorific title in the Qur''an (33:6).'),
 ('ENT_ISL_TEN_PROMISED','PER_ISL_EARLY','The ten companions whom the Prophet reportedly named as assured of paradise during their lifetimes, including Abu Bakr, Umar, Uthman, and Ali.'),
 ('ENT_ISL_ABU_BAKR','PER_ISL_EARLY','Abu Bakr al-Siddiq, the Prophet''s closest companion and father-in-law, who became the first Rightly-Guided Caliph (632-634 CE).'),
 ('ENT_ISL_UMAR','PER_ISL_EARLY','Umar ibn al-Khattab al-Faruq, the second Rightly-Guided Caliph (634-644 CE), under whom the early conquests greatly expanded, renowned for his austere justice.'),
 ('ENT_ISL_UTHMAN','PER_ISL_EARLY','Uthman ibn Affan, the third Rightly-Guided Caliph (644-656 CE), credited with commissioning the standardized written compilation of the Quran, and a son-in-law of the Prophet.'),
 ('ENT_ISL_HAMZA','PER_ISL_EARLY','A paternal uncle of the Prophet, the celebrated warrior titled ''Lion of God,'' killed at the Battle of Uhud (625 CE).'),
 ('ENT_ISL_BILAL','PER_ISL_EARLY','An Abyssinian formerly enslaved and freed by Abu Bakr, an early convert and the first muezzin (caller to prayer) of Islam.'),
 ('ENT_ISL_SALMAN','PER_ISL_EARLY','Salman the Persian, a companion who advised digging the defensive trench at the Battle of the Trench (627 CE) and was honored as a member of the Prophet''s household.'),
 ('ENT_ISL_KHALID','PER_ISL_EARLY','Titled ''Sword of God,'' the foremost military commander of early Islam, leading campaigns in the Ridda wars and the conquests of Iraq and Syria.'),
 ('ENT_ISL_ABU_HURAYRA','PER_ISL_EARLY','A companion who became the most prolific narrator of hadith in the Sunni tradition.'),
 ('ENT_ISL_ZAYD','PER_ISL_EARLY','A freedman and adopted son of the Prophet, the only companion named in the Quran, who died as a commander at the Battle of Mu''ta (629 CE).'),
 ('ENT_ISL_JAFAR','PER_ISL_EARLY','Brother of Ali and cousin of the Prophet, who led the migration to Abyssinia and died as a commander at Mu''ta (629 CE), titled ''Ja''far the Flyer.'''),
 ('ENT_ISL_ABU_TALIB','PER_ISL_EARLY','The paternal uncle who raised the orphaned Muhammad and protected him during the early Meccan persecution as chief of the Banu Hashim.'),
 ('ENT_ISL_ABD_AL_MUTTALIB','PER_ISL_EARLY','The grandfather of the Prophet Muhammad and a leading chief of the Quraysh who served as custodian of the Kaaba in Mecca.'),
 ('ENT_ISL_KHADIJAH','PER_ISL_EARLY','The first wife of the Prophet Muhammad, a wealthy Meccan merchant and the first person to accept Islam.'),
 ('ENT_ISL_AISHA','PER_ISL_EARLY','A wife of the Prophet and daughter of Abu Bakr, who became a foremost narrator of hadith and authority on Islamic law and tradition.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ISR_REHOBOAM','member_of','ENT_ISR_KINGS_JUDAH','high','1 Kings 14:21: Rehoboam reigned in Judah.'),
 ('ENT_ISR_ASA','member_of','ENT_ISR_KINGS_JUDAH','high','1 Kings 15:9-11: Asa king of Judah.'),
 ('ENT_ISR_JEHOSHAPHAT','member_of','ENT_ISR_KINGS_JUDAH','high','1 Kings 22:41: Jehoshaphat king of Judah.'),
 ('ENT_ISR_AHAZ','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 16:1-2: Ahaz king of Judah.'),
 ('ENT_ISR_UZZIAH','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 15:1-2: Azariah/Uzziah king of Judah.'),
 ('ENT_ISR_HEZEKIAH','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 18:1: Hezekiah king of Judah.'),
 ('ENT_ISR_MANASSEH','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 21:1: Manasseh king of Judah.'),
 ('ENT_ISR_JOSIAH','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 22:1: Josiah king of Judah.'),
 ('ENT_ISR_ZEDEKIAH','member_of','ENT_ISR_KINGS_JUDAH','high','2 Kings 24:18: Zedekiah, last king of Judah.'),
 ('ENT_ISR_JEROBOAM_I','member_of','ENT_ISR_KINGS_ISRAEL','high','1 Kings 12:20: Jeroboam made king over Israel.'),
 ('ENT_ISR_OMRI','member_of','ENT_ISR_KINGS_ISRAEL','high','1 Kings 16:16: Omri king over Israel.'),
 ('ENT_ISR_AHAB','member_of','ENT_ISR_KINGS_ISRAEL','high','1 Kings 16:29: Ahab king over Israel.'),
 ('ENT_ISR_JEHU','member_of','ENT_ISR_KINGS_ISRAEL','high','2 Kings 9: Jehu anointed king over Israel.'),
 ('ENT_ISR_JEROBOAM_II','member_of','ENT_ISR_KINGS_ISRAEL','high','2 Kings 14:23: Jeroboam son of Joash king of Israel.'),
 ('ENT_ISR_REHOBOAM','child_of','ENT_ISR_SOLOMON','high','1 Kings 11:43: Rehoboam son of Solomon succeeded him.'),
 ('ENT_ISR_ABSALOM','child_of','ENT_ISR_DAVID','high','2 Samuel 3:3: Absalom son of David.'),
 ('ENT_ISR_JONATHAN','child_of','ENT_ISR_SAUL','high','1 Samuel 13:16: Jonathan son of Saul.'),
 ('ENT_ISR_AHAB','child_of','ENT_ISR_OMRI','high','1 Kings 16:28-29: Ahab son of Omri succeeded him.'),
 ('ENT_ISR_MANASSEH','child_of','ENT_ISR_HEZEKIAH','high','2 Kings 20:21: Manasseh son of Hezekiah succeeded him.'),
 ('ENT_ISR_AHAB','spouse_of','ENT_ISR_JEZEBEL','high','1 Kings 16:31: Ahab took Jezebel to wife.'),
 ('ENT_ISR_BOAZ','spouse_of','ENT_ISR_RUTH','high','Ruth 4:13: Boaz took Ruth and she became his wife.'),
 ('ENT_ISR_NAOMI','paired_with','ENT_ISR_RUTH','high','Ruth 1:16-18: Ruth clings to Naomi as her mother-in-law and companion.'),
 ('ENT_ISR_ELIJAH','opposes','ENT_ISR_AHAB','high','1 Kings 17-21: Elijah repeatedly confronts Ahab over Baal worship and the Naboth affair.'),
 ('ENT_ISR_ELIJAH','opposes','ENT_ISR_JEZEBEL','high','1 Kings 18-19: Elijah opposes Jezebel, who seeks his life after the Carmel contest.'),
 ('ENT_ISR_GOLIATH','slain_by','ENT_ISR_DAVID','high','1 Samuel 17:49-51: David struck down Goliath.'),
 ('ENT_ISR_DELILAH','opposes','ENT_ISR_SAMSON','high','Judges 16: Delilah betrays Samson to the Philistine lords.'),
 ('ENT_ISR_ABSALOM','opposes','ENT_ISR_DAVID','high','2 Samuel 15-18: Absalom rebels against his father David.'),
 ('ENT_ISR_NEBUCHADNEZZAR','opposes','ENT_ISR_ZEDEKIAH','high','2 Kings 25:1-7: Nebuchadnezzar besieges Jerusalem and captures and blinds Zedekiah.'),
 ('ENT_ISR_NAAMAN','mediated_by','ENT_ISR_ELISHA','high','2 Kings 5: Naaman cured of leprosy through Elisha''s instruction.'),
 ('ENT_ISR_HEZEKIAH','mediated_by','ENT_ISR_ISAIAH','high','2 Kings 19-20: Isaiah delivers Yahweh''s word to Hezekiah during the siege and his illness.'),
 ('ENT_ISR_CYRUS','patron_of','ENT_ISR_EZRA','medium','Ezra 1:1-4: Cyrus''s decree authorizes the return and rebuilding that Ezra advances.'),
 ('ENT_ISR_JOSIAH','presides_over','ENT_JUSTICE','medium','2 Kings 22-23: Josiah''s covenant reform exemplifies righteous rule.'),
 ('ENT_ISR_JEZEBEL','presides_over','ENT_DECEPTION','medium','1 Kings 21: Jezebel orchestrates false witnesses to seize Naboth''s vineyard.'),
 ('ENT_NT_PHILIP_EVANGELIST','member_of','ENT_NT_SEVEN_DEACONS','high','Acts 6:5 names Philip among the Seven; Acts 21:8 calls him ''one of the seven.'''),
 ('ENT_CHR_STEPHEN','member_of','ENT_NT_SEVEN_DEACONS','high','Acts 6:5 lists Stephen first among the Seven; he is the protomartyr.'),
 ('ENT_NT_MARY_BETHANY','sibling_of','ENT_NT_LAZARUS_BETHANY','high','John 11:1-2: Mary and Martha are the sisters of Lazarus.'),
 ('ENT_NT_MARY_BETHANY','sibling_of','ENT_NT_MARTHA','high','Luke 10:38-42; John 11: Mary and Martha are sisters at Bethany.'),
 ('ENT_NT_JAMES_JUST','sibling_of','ENT_JESUS_CHRIST','medium','Galatians 1:19 calls James ''the Lord''s brother''; tradition varies on the exact relation.'),
 ('ENT_NT_JUDE','sibling_of','ENT_JESUS_CHRIST','medium','Mark 6:3 names Judas among the brothers of Jesus; Jude 1:1 calls him ''brother of James.'''),
 ('ENT_NT_PRISCILLA','spouse_of','ENT_NT_AQUILA','high','Acts 18:2; Romans 16:3: Priscilla and Aquila are a married missionary couple.'),
 ('ENT_NT_SILAS','member_of','ENT_NT_PAULINE_CIRCLE','high','Acts 15:40-18:5: Silas a coworker and co-sender with Paul.'),
 ('ENT_NT_APOLLOS','member_of','ENT_NT_PAULINE_CIRCLE','high','1 Corinthians 3:5-9; Acts 18:24-28: Apollos a fellow worker in the Pauline mission.'),
 ('ENT_NT_PRISCILLA','member_of','ENT_NT_PAULINE_CIRCLE','high','Romans 16:3: Prisca a ''fellow worker in Christ Jesus.'''),
 ('ENT_NT_AQUILA','member_of','ENT_NT_PAULINE_CIRCLE','high','Romans 16:3; Acts 18: Aquila a coworker and host of Paul.'),
 ('ENT_NT_SALOME','member_of','ENT_NT_MYRRHBEARERS','high','Mark 16:1 names Salome among the women who came to anoint Jesus'' body.'),
 ('ENT_NT_MARY_BETHANY','member_of','ENT_NT_MYRRHBEARERS','medium','Eastern tradition counts Mary of Bethany among the myrrh-bearing women.'),
 ('ENT_NT_MARY_OF_JAMES','member_of','ENT_NT_MYRRHBEARERS','high','Mark 16:1; Luke 24:10 name Mary the mother of James among the women at the tomb.'),
 ('ENT_SAINT_MARY_MAGDALENE','member_of','ENT_NT_MYRRHBEARERS','high','All four Gospels place Mary Magdalene foremost among the myrrh-bearers.'),
 ('ENT_NT_PILATE','opposes','ENT_JESUS_CHRIST','high','All four Gospels: Pilate is the judge who condemned Jesus to crucifixion.'),
 ('ENT_NT_CAIAPHAS','opposes','ENT_JESUS_CHRIST','high','Matthew 26:57-66; John 11:49-53: Caiaphas presided over the case against Jesus.'),
 ('ENT_NT_HEROD_GREAT','opposes','ENT_JESUS_CHRIST','high','Matthew 2: Herod the Great sought the infant Jesus'' life (the Massacre of the Innocents).'),
 ('ENT_NT_HEROD_ANTIPAS','opposes','ENT_SAINT_JOHN_BAPTIST','high','Mark 6:14-29: Herod Antipas imprisoned and beheaded John the Baptist.'),
 ('ENT_ISL_ABU_BAKR','member_of','ENT_ISL_RASHIDUN','high','Abu Bakr was the first of the four Rashidun caliphs (632-634 CE).'),
 ('ENT_ISL_UMAR','member_of','ENT_ISL_RASHIDUN','high','Umar was the second of the four Rashidun caliphs (634-644 CE).'),
 ('ENT_ISL_UTHMAN','member_of','ENT_ISL_RASHIDUN','high','Uthman was the third of the four Rashidun caliphs (644-656 CE).'),
